{
  "name": "mini-template",
  "version": "1.0.0",
  "description": "A dependency-free TypeScript template renderer for Bun.",
  "type": "module",
  "scripts": {
    "test": "bun test",
    "start": "bun run src/cli.ts"
  }
}

// Mini Template — a dependency-free TypeScript template renderer.
// Supports: escaped/unescaped interpolation, if/else, each/else, comments,
// `this` and `@index` inside each blocks, nested blocks, and strict errors.

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface Frame {
  data: unknown;
  parent: Frame | null;
  index: number | null;
}

type Node =
  | { type: "text"; value: string }
  | { type: "escape"; path: string; line: number; col: number }
  | { type: "raw"; path: string; line: number; col: number }
  | { type: "comment" }
  | { type: "if"; path: string; line: number; col: number; branches: [Node[], Node[]] }
  | { type: "each"; path: string; line: number; col: number; branches: [Node[], Node[]] };

// ---------------------------------------------------------------------------
// Tokenizer
// ---------------------------------------------------------------------------

const RAW = /^{{{([^]*?)}}}/;
const TAG = /^\{\{([^}]*?)\}\}/;

interface Token {
  kind: "text" | "raw" | "tag";
  value: string;
  line: number;
  col: number;
}

function tokenize(src: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  let line = 1;
  let col = 1;

  while (i < src.length) {
    if (src[i] === "{") {
      // Try raw triple-brace first: {{{...}}}
      const rest = src.slice(i);
      const rawMatch = rest.match(RAW);
      if (rawMatch) {
        const content = rawMatch[1];
        tokens.push({ kind: "raw", value: content, line, col });
        const full = rawMatch[0];
        for (let k = 0; k < full.length; k++) advance();
        continue;
      }
      // Try double-brace: {{...}}
      const tagMatch = rest.match(TAG);
      if (tagMatch) {
        const content = tagMatch[1];
        tokens.push({ kind: "tag", value: content, line, col });
        const full = tagMatch[0];
        for (let k = 0; k < full.length; k++) advance();
        continue;
      }
    }
    // Regular text up to the next opening brace
    let text = "";
    while (i < src.length && src[i] !== "{") {
      text += src[i];
      advance();
    }
    if (text) tokens.push({ kind: "text", value: text, line, col: col - text.length });
  }

  function advance(): void {
    if (src[i] === "\n") {
      line++;
      col = 1;
    } else {
      col++;
    }
    i++;
  }

  return tokens;
}

// ---------------------------------------------------------------------------
// Parser (tokens -> AST)
// ---------------------------------------------------------------------------

interface ParseResult {
  nodes: Node[];
  consumed: number; // tokens consumed
}

function parse(tokens: Token[]): Node[] {
  const result = parseUntil(tokens, 0, null);
  if (result.consumed !== tokens.length) {
    const t = tokens[result.consumed];
    if (t && (t.kind === "tag")) {
      const v = t.value.trim();
      if (v.startsWith("/")) {
        throw errStr(t, `Unexpected {{${v}}} — close without matching open`);
      }
      if (v.startsWith("else")) {
        throw errStr(t, `{{else}} without a containing block`);
      }
    }
    throw errStr(t, "Unexpected trailing tokens");
  }
  return result.nodes;
}

interface StopCond {
  /** Return "body", "else", or null if this token is not a stop token. */
  match: (content: string) => "body" | "else" | null;
  kind: string;
}

function parseUntil(tokens: Token[], start: number, stop: StopCond | null): ParseResult {
  const nodes: Node[] = [];
  let i = start;

  while (i < tokens.length) {
    const t = tokens[i];

    if (t.kind === "text") {
      nodes.push({ type: "text", value: t.value });
      i++;
      continue;
    }

    if (t.kind === "raw") {
      const path = t.value.trim();
      nodes.push({ type: "raw", path, line: t.line, col: t.col });
      i++;
      continue;
    }

    // t.kind === "tag"
    const content = t.value;
    const trimmed = content.trim();

    // Comment: {{! ... }}
    if (trimmed.startsWith("!")) {
      nodes.push({ type: "comment" });
      i++;
      continue;
    }

    // Check stop condition ({{else}} or {{/block}})
    if (stop) {
      const stopKind = stop.match(trimmed);
      if (stopKind !== null) {
        return { nodes, consumed: i - start, _stopKind: stopKind, _stopToken: t } as ParseResult;
      }
    }

    // Block openers: {{#if path}} and {{#each path}}
    if (trimmed.startsWith("#if ")) {
      const path = trimmed.slice(4).trim();
      const res = parseBlock(tokens, i + 1, "if", path, t);
      nodes.push(res.node);
      i = i + 1 + res.consumed;
      continue;
    }
    if (trimmed.startsWith("#each ")) {
      const path = trimmed.slice(6).trim();
      const res = parseBlock(tokens, i + 1, "each", path, t);
      nodes.push(res.node);
      i = i + 1 + res.consumed;
      continue;
    }

    // Bare {{else}}, {{/if}}, {{/each}} at top level (not inside a block) — error
    if (trimmed === "else") {
      throw errStr(t, `{{else}} without a containing block`);
    }
    if (trimmed.startsWith("/")) {
      throw errStr(t, `Unexpected {{${trimmed}}} — close without matching open`);
    }

    // Otherwise it's an escaped interpolation: {{path.to.value}}
    nodes.push({ type: "escape", path: trimmed, line: t.line, col: t.col });
    i++;
  }

  if (stop) {
    throw errStr(tokens[start] || { line: 1, col: 1 }, `Unclosed {{#${stop.kind}}} — missing {{/${stop.kind}}}`);
  }
  return { nodes, consumed: i - start };
}

interface BlockParseResult {
  node: Node;
  consumed: number; // tokens consumed after the opening tag (not counting the opener)
}

function parseBlock(
  tokens: Token[],
  start: number,
  kind: "if" | "each",
  path: string,
  opener: Token
): BlockParseResult {
  if (!path) {
    throw errStr(opener, `Empty path in {{#${kind}}}`);
  }

  // Parse the body (until {{else}} or {{/kind}})
  const bodyResult = parseUntil(tokens, start, {
    kind,
    match: (content: string): "body" | "else" | null => {
      if (content === "else") return "else";
      if (content === `/${kind}`) return "body";
      return null;
    },
  }) as ParseResult & { _stopKind?: string; _stopToken?: Token };

  // If no stop was hit, the block is unclosed
  if (bodyResult.consumed >= tokens.length - start && bodyResult._stopKind === undefined) {
    // parseUntil would have thrown already if stop was set and we ran out
    // but let's be safe
    throw errStr(opener, `Unclosed {{#${kind}}} — missing {{/${kind}}}`);
  }

  const stopKind = bodyResult._stopKind!;
  const stopToken = bodyResult._stopToken!;
  let bodyNodes = bodyResult.nodes;
  let elseNodes: Node[] = [];
  let consumed = bodyResult.consumed + 1; // +1 for the stop token
  let nextIndex = start + bodyResult.consumed + 1;

  if (stopKind === "else") {
    // We stopped at {{else}}, now parse the else-body until {{/kind}}
    const elseResult = parseUntil(tokens, nextIndex, {
      kind,
      match: (content: string): "body" | "else" | null => {
        if (content === `/${kind}`) return "body";
        if (content === "else") return "else";
        return null;
      },
    }) as ParseResult & { _stopKind?: string; _stopToken?: Token };

    if (elseResult._stopKind === undefined && elseResult._stopKind !== "body") {
      // Ran out without a close
      if (elseResult._stopKind === "else") {
        throw errStr(elseResult._stopToken!, `Duplicate {{else}} in {{#${kind}}} block`);
      }
      throw errStr(opener, `Unclosed {{#${kind}}} — missing {{/${kind}}}`);
    }

    elseNodes = elseResult.nodes;
    consumed += elseResult.consumed + 1; // +1 for the closing token
    nextIndex = nextIndex + elseResult.consumed + 1;
  }

  // Verify the closing token is {{/kind}}
  const closer = tokens[nextIndex - 1];
  if (!closer || closer.kind !== "tag" || closer.value.trim() !== `/${kind}`) {
    throw errStr(opener, `Unclosed {{#${kind}}} — missing {{/${kind}}}`);
  }

  const node: Node =
    kind === "if"
      ? { type: "if", path, line: opener.line, col: opener.col, branches: [bodyNodes, elseNodes] }
      : { type: "each", path, line: opener.line, col: opener.col, branches: [bodyNodes, elseNodes] };

  return { node, consumed };
}

// ---------------------------------------------------------------------------
// Utility functions
// ---------------------------------------------------------------------------

function errStr(t: { line: number; col: number }, message: string): Error {
  return new Error(`line ${t.line}, col ${t.col}: ${message}`);
}

const ESC_MAP: Record<string, string> = {
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&#39;",
};

function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => ESC_MAP[c]);
}

function lookup(path: string, frame: Frame): unknown {
  if (path === "this") {
    return frame.data;
  }
  if (path === "@index") {
    return frame.index;
  }

  const parts = path.split(".");
  let current: unknown = frame.data;
  let fromRoot = true;

  for (const part of parts) {
    if (part === "") {
      throw new Error(`Invalid empty segment in path "${path}"`);
    }
    if (current == null) {
      return undefined;
    }
    if (typeof current !== "object") {
      return undefined;
    }
    if (Array.isArray(current)) {
      // Arrays: numeric index access
      if (/^\d+$/.test(part)) {
        current = current[parseInt(part, 10)];
        fromRoot = false;
        continue;
      }
      // Non-numeric key on array — fall through to property access
    }
    if (part in (current as Record<string, unknown>)) {
      current = (current as Record<string, unknown>)[part];
      fromRoot = false;
    } else if (fromRoot && frame.parent) {
      // Fallback to parent scope (root object per spec)
      current = lookup(path, frame.parent);
      return current;
    } else {
      return undefined;
    }
  }
  return current;
}

function toScalar(value: unknown, path: string, line: number, col: number, escape: boolean): string {
  if (value === null || value === undefined) {
    return "";
  }
  const t = typeof value;
  if (t === "string") {
    return escape ? escapeHtml(value) : value;
  }
  if (t === "number" || t === "boolean") {
    const s = String(value);
    return escape ? escapeHtml(s) : s;
  }
  // Objects, functions, symbols, bigint — error
  throw errStr({ line, col }, `Cannot render ${t} value at "${path}" as text`);
}

function isTruthy(value: unknown): boolean {
  if (value === null || value === undefined) return false;
  if (value === false) return false;
  if (value === 0) return false;
  if (value === "") return false;
  if (Array.isArray(value)) return value.length > 0;
  if (typeof value === "object") {
    const obj = value as Record<string, unknown>;
    // Empty object is false per spec? Spec says "empty arrays are false"
    // but objects aren't explicitly mentioned. Let's treat empty object as false.
    if (Object.keys(obj).length === 0) return false;
    return true;
  }
  return true;
}

// ---------------------------------------------------------------------------
// Renderer
// ---------------------------------------------------------------------------

function renderNodes(nodes: Node[], frame: Frame): string {
  let out = "";
  for (const node of nodes) {
    out += renderNode(node, frame);
  }
  return out;
}

function renderNode(node: Node, frame: Frame): string {
  switch (node.type) {
    case "text":
      return node.value;
    case "comment":
      return "";
    case "escape":
      return toScalar(lookup(node.path, frame), node.path, node.line, node.col, true);
    case "raw":
      return toScalar(lookup(node.path, frame), node.path, node.line, node.col, false);
    case "if": {
      const value = lookup(node.path, frame);
      if (isTruthy(value)) {
        return renderNodes(node.branches[0], frame);
      }
      return renderNodes(node.branches[1], frame);
    }
    case "each": {
      const value = lookup(node.path, frame);
      if (!Array.isArray(value)) {
        return renderNodes(node.branches[1], frame);
      }
      if (value.length === 0) {
        return renderNodes(node.branches[1], frame);
      }
      let out = "";
      for (let idx = 0; idx < value.length; idx++) {
        const childFrame: Frame = {
          data: value[idx],
          parent: frame,
          index: idx,
        };
        out += renderNodes(node.branches[0], childFrame);
      }
      return out;
    }
  }
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

export function render(template: string, data: unknown): string {
  const tokens = tokenize(template);
  const ast = parse(tokens);
  const rootFrame: Frame = { data, parent: null, index: null };
  return renderNodes(ast, rootFrame);
}

#!/usr/bin/env bun
import { render } from "./engine.ts";

const args = process.argv.slice(2);

if (args.length !== 2) {
  process.stderr.write("Usage: bun run src/cli.ts TEMPLATE_FILE DATA.json\n");
  process.exit(1);
}

const [templatePath, dataPath] = args;

try {
  const templateFile = Bun.file(templatePath);
  const dataFile = Bun.file(dataPath);

  if (!await templateFile.exists()) {
    process.stderr.write(`Error: template file not found: ${templatePath}\n`);
    process.exit(1);
  }
  if (!await dataFile.exists()) {
    process.stderr.write(`Error: data file not found: ${dataPath}\n`);
    process.exit(1);
  }

  const template = await templateFile.text();
  const dataText = await dataFile.text();

  let data: unknown;
  try {
    data = JSON.parse(dataText);
  } catch (e) {
    process.stderr.write(`Error: invalid JSON in ${dataPath}: ${(e as Error).message}\n`);
    process.exit(1);
  }

  const output = render(template, data);
  process.stdout.write(output);
} catch (e) {
  process.stderr.write(`Error: ${(e as Error).message}\n`);
  process.exit(1);
}

