import { test, expect } from "bun:test";
import { render } from "../src/engine.ts";

// ---------------------------------------------------------------------------
// Escaped interpolation
// ---------------------------------------------------------------------------

test("escaped interpolation escapes HTML entities", () => {
  expect(render("{{x}}", { x: '<b>&"\'</b>' })).toBe("&lt;b&gt;&amp;&quot;&#39;&lt;/b&gt;");
});

test("escaped interpolation with simple string", () => {
  expect(render("Hello, {{name}}!", { name: "World" })).toBe("Hello, World!");
});

test("escaped interpolation with nested path", () => {
  expect(render("{{a.b.c}}", { a: { b: { c: "deep" } } })).toBe("deep");
});

test("missing value renders as empty string", () => {
  expect(render("[{{nope}}]", {})).toBe("[]");
});

test("undefined nested path renders as empty string", () => {
  expect(render("[{{a.b.c}}]", { a: {} })).toBe("[]");
});

test("numbers render as their string form", () => {
  expect(render("{{n}}", { n: 42 })).toBe("42");
});

test("booleans render as true/false", () => {
  expect(render("{{t}}/{{f}}", { t: true, f: false })).toBe("true/false");
});

test("zero renders as 0 not empty", () => {
  expect(render("{{z}}", { z: 0 })).toBe("0");
});

// ---------------------------------------------------------------------------
// Unescaped (raw) interpolation
// ---------------------------------------------------------------------------

test("raw triple-brace interpolation does not escape", () => {
  expect(render("{{{x}}}", { x: "<b>hi</b>" })).toBe("<b>hi</b>");
});

test("raw interpolation with nested path", () => {
  expect(render("{{{a.b}}}", { a: { b: "<x>" } })).toBe("<x>");
});

test("raw interpolation with missing value renders empty", () => {
  expect(render("[{{{nope}}}]", {})).toBe("[]");
});

// ---------------------------------------------------------------------------
// Comments
// ---------------------------------------------------------------------------

test("comments emit nothing", () => {
  expect(render("a{{! this is a comment }}b", {})).toBe("ab");
});

test("comment with special chars in content", () => {
  expect(render("{{! <b> & " ' }}", {})).toBe("");
});

test("comment in the middle of text", () => {
  expect(render("Hello{{! ignore me }} World", {})).toBe("Hello World");
});

// ---------------------------------------------------------------------------
// if / else
// ---------------------------------------------------------------------------

test("if true renders body", () => {
  expect(render("{{#if x}}yes{{/if}}", { x: true })).toBe("yes");
});

test("if false renders empty", () => {
  expect(render("{{#if x}}yes{{/if}}", { x: false })).toBe("");
});

test("if false with else renders else", () => {
  expect(render("{{#if x}}yes{{else}}no{{/if}}", { x: false })).toBe("no");
});

test("if true with else renders body not else", () => {
  expect(render("{{#if x}}yes{{else}}no{{/if}}", { x: true })).toBe("no".replace("no", "yes")));
});

test("if with empty string is false", () => {
  expect(render("{{#if x}}yes{{else}}no{{/if}}", { x: "" })).toBe("no");
});

test("if with zero is false", () => {
  expect(render("{{#if x}}yes{{else}}no{{/if}}", { x: 0 })).toBe("no");
});

test("if with null is false", () => {
  expect(render("{{#if x}}yes{{else}}no{{/if}}", { x: null })).toBe("no");
});

test("if with undefined is false", () => {
  expect(render("{{#if x}}yes{{else}}no{{/if}}", { x: undefined })).toBe("no");
});

test("if with empty array is false", () => {
  expect(render("{{#if x}}yes{{else}}no{{/if}}", { x: [] })).toBe("no");
});

test("if with non-empty array is true", () => {
  expect(render("{{#if x}}yes{{else}}no{{/if}}", { x: [1] })).toBe("yes");
});

test("if with non-empty object is true", () => {
  expect(render("{{#if x}}yes{{else}}no{{/if}}", { x: { a: 1 } })).toBe("yes");
});

test("if with nested path", () => {
  expect(render("{{#if a.b}}yes{{else}}no{{/if}}", { a: { b: true } })).toBe("yes");
});

test("nested if blocks", () => {
  const tpl = "{{#if a}}{{#if b}}AB{{else}}A{{/if}}{{else}}notA{{/if}}";
  expect(render(tpl, { a: true, b: true })).toBe("AB");
  expect(render(tpl, { a: true, b: false })).toBe("A");
  expect(render(tpl, { a: false, b: true })).toBe("notA");
});

// ---------------------------------------------------------------------------
// each / else
// ---------------------------------------------------------------------------

test("each iterates array", () => {
  expect(render("{{#each items}}{{this}},{{/each}}", { items: ["a", "b", "c"] })).toBe("a,b,c,");
});

test("each with @index", () => {
  expect(render("{{#each items}}{{@index}}:{{this}} {{/each}}", { items: ["x", "y"] })).toBe("0:x 1:y ");
});

test("each with empty array renders else", () => {
  expect(render("{{#each items}}{{this}}{{else}}empty{{/each}}", { items: [] })).toBe("empty");
});

test("each with missing array renders else", () => {
  expect(render("{{#each items}}{{this}}{{else}}none{{/each}}", {})).toBe("none");
});

test("each with non-array value renders else", () => {
  expect(render("{{#each items}}{{this}}{{else}}notarr{{/each}}", { items: "hello" })).toBe("notarr");
});

test("nested each blocks", () => {
  const tpl = "{{#each matrix}}[{{#each this}}{{this}},{{/each}}]{{/each}}";
  const data = { matrix: [["a", "b"], ["c", "d"]] };
  expect(render(tpl, data)).toBe("[a,b,][c,d,]");
});

test("each with property access on items", () => {
  const tpl = "{{#each users}}{{name}} {{/each}}";
  const data = { users: [{ name: "Alice" }, { name: "Bob" }] };
  expect(render(tpl, data)).toBe("Alice Bob ");
});

test("each item accesses root via fallback", () => {
  const tpl = "{{#each items}}{{this}}-{{root}}{{/each}}";
  const data = { items: [1, 2], root: "R" };
  expect(render(tpl, data)).toBe("1-R2-R");
});

// ---------------------------------------------------------------------------
// Whitespace preservation
// ---------------------------------------------------------------------------

test("whitespace outside tags is preserved", () => {
  expect(render("  {{x}}  ", { x: "v" })).toBe("  v  ");
});

test("newlines preserved", () => {
  expect(render("line1\n{{x}}\nline3", { x: "line2" })).toBe("line1\nline2\nline3");
});

test("whitespace around blocks preserved", () => {
  const tpl = "  {{#if x}}\n    yes\n  {{/if}}  ";
  expect(render(tpl, { x: true })).toBe("  \n    yes\n    ");
});

// ---------------------------------------------------------------------------
// Combined / complex
// ---------------------------------------------------------------------------

test("if inside each", () => {
  const tpl = "{{#each items}}{{#if this.active}}{{this.name}} {{/if}}{{/each}}";
  const data = {
    items: [
      { name: "A", active: true },
      { name: "B", active: false },
      { name: "C", active: true },
    ],
  };
  expect(render(tpl, data)).toBe("A C ");
});

test("each inside if", () => {
  const tpl = "{{#if show}}{{#each items}}{{this}} {{/each}}{{/if}}";
  expect(render(tpl, { show: true, items: [1, 2, 3] })).toBe("1 2 3 ");
  expect(render(tpl, { show: false, items: [1, 2, 3] })).toBe("");
});

test("mixed escaped and raw", () => {
  expect(render("{{esc}} | {{{raw}}}", { esc: "<b>", raw: "<i>" })).toBe("&lt;b&gt; | <i>");
});

// ---------------------------------------------------------------------------
// Error cases
// ---------------------------------------------------------------------------

test("rendering object value throws clear error", () => {
  expect(() => render("{{x}}", { x: { a: 1 } })).toThrow(/Cannot render object/);
});

test("rendering function value throws clear error", () => {
  expect(() => render("{{x}}", { x: () => 1 })).toThrow(/Cannot render function/);
});

test("unclosed if throws with line info", () => {
  expect(() => render("{{#if x}}no close", { x: true })).toThrow(/line/);
});

test("unclosed each throws with line info", () => {
  expect(() => render("{{#each x}}no close", { x: [] })).toThrow(/line/);
});

test("mismatched close tag throws", () => {
  expect(() => render("{{#if x}}body{{/each}}", { x: true })).toThrow();
});

test("else outside block throws", () => {
  expect(() => render("text {{else}}", {})).toThrow(/else/);
});

test("duplicate else throws", () => {
  expect(() => render("{{#if x}}a{{else}}b{{else}}c{{/if}}", { x: true })).toThrow(/Duplicate/);
});

test("unknown block throws", () => {
  expect(() => render("{{#unknown x}}{{/unknown}}", {})).toThrow();
});

test("error includes line and column", () => {
  try {
    render("\n\n{{x}}\n{{x}}", { x: { a: 1 } });
    expect(false).toBe(true);
  } catch (e) {
    expect((e as Error).message).toMatch(/line \d+, col \d+/);
  }
});

import { test, expect } from "bun:test";
import { $ } from "bun";

const CLI = "src/cli.ts";

async function runCli(templateFile: string, dataFile: string): Promise<{ stdout: string; stderr: string; exitCode: number }> {
  const proc = Bun.spawn(["bun", "run", CLI, templateFile, dataFile], {
    cwd: import.meta.dir + "/..",
    stdout: "pipe",
    stderr: "pipe",
  });
  const [stdout, stderr] = await Promise.all([
    new Response(proc.stdout).text(),
    new Response(proc.stderr).text(),
  ]);
  const exitCode = await proc.exited;
  return { stdout, stderr, exitCode };
}

async function writeTemp(content: string, suffix: string): Promise<string> {
  const path = `${import.meta.dir}/.tmp-${Date.now()}-${Math.random().toString(36).slice(2)}${suffix}`;
  await Bun.write(path, content);
  return path;
}

test("CLI renders template with data", async () => {
  const tpl = await writeTemp("Hello, {{name}}!", ".tpl");
  const data = await writeTemp(JSON.stringify({ name: "World" }), ".json");
  const { stdout, exitCode } = await runCli(tpl, data);
  expect(exitCode).toBe(0);
  expect(stdout).toBe("Hello, World!");
});

test("CLI outputs only rendered text to stdout", async () => {
  const tpl = await writeTemp("{{a}} {{b}}", ".tpl");
  const data = await writeTemp(JSON.stringify({ a: "1", b: "2" }), ".json");
  const { stdout, exitCode } = await runCli(tpl, data);
  expect(exitCode).toBe(0);
  expect(stdout).toBe("1 2");
});

test("CLI errors go to stderr with non-zero exit", async () => {
  const tpl = await writeTemp("{{x}}", ".tpl");
  const data = await writeTemp(JSON.stringify({ x: { a: 1 } }), ".json");
  const { stderr, exitCode } = await runCli(tpl, data);
  expect(exitCode).not.toBe(0);
  expect(stderr.length).toBeGreaterThan(0);
});

test("CLI handles missing template file", async () => {
  const data = await writeTemp(JSON.stringify({}), ".json");
