function lookup(path: string, frame: Frame): unknown {
  if (path === "this") {
    return frame.data;
  }
  if (path === "@index") {
    return frame.index;
  }

  // Handle "this." prefix — start from current frame's data
  let parts = path.split(".");
  let current: unknown = frame.data;

  if (parts[0] === "this") {
    parts = parts.slice(1);
    current = frame.data;
  } else if (frame.parent && !Object.hasOwn(frame.data as object, parts[0])) {
    // If the first key doesn't exist on current scope, fall back to root
    current = frame.parent.data;
  }

  for (const part of parts) {
    if (part === "") {
      throw new Error(`Invalid empty segment in path "${path}"`);
    }
    if (current == null) {
      return undefined;
    }
    if (typeof current !== "object") {
      return undefined;
    }

