// ---------------------------------------------------------------------------
// Edge cases
// ---------------------------------------------------------------------------

test("each with null items in array", () => {
  const tpl = "{{#each items}}[{{this}}]{{/each}}";
  expect(render(tpl, { items: [null, "a", null] })).toBe("[][a][]");
});

test("each with nested this access", () => {
  const tpl = "{{#each users}}{{this.name}}:{{this.age}} {{/each}}";
  const data = { users: [{ name: "A", age: 1 }, { name: "B", age: 2 }] };
  expect(render(tpl, data)).toBe("A:1 B:2 ");
});

test("nested each with @index", () => {
  const tpl = "{{#each outer}}{{#each this}}{{@index}}:{{this}} {{/each}}|{{/each}}";
  const data = { outer: [["a", "b"], ["c"]] };
  expect(render(tpl, data)).toBe("0:a 1:b |0:c |");
});

test("root with primitive data", () => {
  expect(render("{{this}}", "hello")).toBe("hello");
});

test("root with null data", () => {
  expect(render("[{{this}}]", null)).toBe("[]");
});

test("empty template renders empty", () => {
  expect(render("", { x: 1 })).toBe("");
});

test("template with no tags passes through", () => {
  expect(render("just plain text", {})).toBe("just plain text");
});

test("if with missing path is false", () => {
  expect(render("{{#if missing}}yes{{else}}no{{/if}}", {})).toBe("no");
});

test("each with @index in if", () => {
  const tpl = "{{#each items}}{{#if @index}}{{this}}{{/if}}{{/each}}";
  // @index is 0 for first item (falsy), 1+ for rest (truthy)
  expect(render(tpl, { items: ["a", "b", "c"] })).toBe("bc");
});

test("multiple interpolations on same line", () => {
  expect(render("{{a}}{{b}}{{c}}", { a: 1, b: 2, c: 3 })).toBe("123");
});

test("text between blocks", () => {
  const tpl = "a{{#if x}}b{{/if}}c{{#if y}}d{{/if}}e";
  expect(render(tpl, { x: true, y: true })).toBe("abcde");
  expect(render(tpl, { x: false, y: true })).toBe("acde");
});

